import{_ as t,l,o as e,c as i,v as o,p as s,x as n,d as m,i as h,S as d}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"Chameleon 早期融合","description":"","frontmatter":{"title":"Chameleon 早期融合","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/chameleon.md","filePath":"llm/chameleon.md","lastUpdated":1789023840000}'),p={name:"llm/chameleon.md"};function E(c,a,B,u,A,C){const r=l("Mermaid");return e(),i("div",null,[a[1]||(a[1]=o('<h1 id="chameleon-早期融合" tabindex="-1">Chameleon 早期融合 <a class="header-anchor" href="#chameleon-早期融合" aria-label="Permalink to &quot;Chameleon 早期融合&quot;">​</a></h1><div class="epigraph"><p>把图像量化成与词同一套离散符号，从第一层自注意力起就在混合序列上做下一 token 预测；早期融合的难点不是概念，而是 softmax 在两种熵差很大的符号上如何不炸。</p><footer>—— Chameleon Team，Chameleon: Mixed-Modal Early-Fusion Foundation Models，arXiv:2405.09818</footer></div><p>Meta FAIR 2024 年 5 月的 <strong>Chameleon</strong> 是 7B / 34B 稠密 Transformer：图像经 VQ 码本变成离散 token，与文本 BPE 共享词表，<strong>从零</strong>在混合模态上训因果语言模型。它要既能看图写字，也能在同一条序列里生成图像码，再解码成像素。这与 Flamingo / LLaVA 把连续视觉向量晚接入冻结或微调 LLM 不同，论文称之为 <strong>early-fusion、token-based</strong>。公开权重面向研究、图生图能力因安全未放。本篇按 arXiv:2405.09818 写架构、稳定化与词表，不把后续未写入该报告的产品名倒填进来。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>晚融合把「理解图像」交给 CLIP 一类编码器，语言模型只读投影后的连续前缀或交叉注意力记忆：生成图像要另接扩散头，交错文档里「写到一半插一张图」不是同一套损失。<a href="/llm/interleaved-multimodal">交错训练</a> 可以只预测文本；若还要图文混生，图像必须进入与词相同的离散空间，否则解码器没有可采样的图像符号。早期融合的优化问题立刻出现：文本 token 条件熵低、图像码条件熵高，同一 softmax 里两类 logits 尺度打架，深层的注意力与最终词表都容易发散。Llama-2 的预归一化配方在纯文本 2T 上稳，在混合 4.4T 上不够。</p><p>第二个问题是码本本身。\\(512\\times 512\\) 图编成 <strong>1024</strong> 个离散码（约 \\(32\\times 32\\) 网格），码本大小 <strong>8192</strong>，文本 BPE 词表 <strong>65536</strong>（含这 8192 个图像码）。码本弱重建——尤其是图里的字——会给整个模型的 OCR 封顶。论文用授权图像训 tokenizer，人脸过采样约 2 倍，并写明文字重建是核心弱点。</p><h3 id="统一词表-不是两个模型的加权和" tabindex="-1">统一词表，不是两个模型的加权和 <a class="header-anchor" href="#统一词表-不是两个模型的加权和" aria-label="Permalink to &quot;统一词表，不是两个模型的加权和&quot;">​</a></h3><p>早期融合的操作定义是：任意图文交错序列 \\(z_{1:n}\\) 上</p> \\[\\mathcal{L}=-\\sum_t \\log p_\\theta(z_t\\mid z_{\\lt t}), \\]<p>\\(z_t\\) 既可以是子词也可以是图像码。没有单独的图像交叉层，也没有「先看完图再读字」的路由。Gemini 同期也走原生多模态，但报告写明 Gemini 用<strong>单独的图像解码器</strong>；Chameleon 强调自己是端到端稠密、无路由。不要把两者画成同一张结构图。</p><p><span class="marginnote">公开检查点是研究许可下的「混合输入、文本输出」安全对齐版。论文评测里的图像生成与长文混生，不等于 Hugging Face 上能采样图像码。部署前读卡片，不要假设权重覆盖论文全部生成面。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>骨干相对 Llama-2：上下文 4K，7B 无 GQA、34B 有 GQA，预训练 <strong>4.4T</strong> token，峰值学习率 \\(1.0\\times 10^{-4}\\)，AdamW。图像 tokenizer 基于 Gafni 等（2022）的量化器。为压住注意力 softmax 的输入范数，引入 <strong>QK-Norm</strong>：对 \\(q,k\\) 做层归一化再点积。7B 还曾用注意力与 FFN 后 dropout 0.1；34B 额外采用 Swin 式 <strong>norm reordering</strong>，把范数增长限制在 SwiGLU 乘法放大之前，并去掉 dropout。最终 softmax 的配分函数用 <strong>z-loss</strong> \\(10^{-5}\\log^2 Z\\) 正则，减轻 logit 漂移。论文消融：无 QK-Norm 时 7B 约在 20% epoch 处发散；QK-Norm 对两档都必要。</p><h3 id="对齐与评测面" tabindex="-1">对齐与评测面 <a class="header-anchor" href="#对齐与评测面" aria-label="Permalink to &quot;对齐与评测面&quot;">​</a></h3><p>SFT 把提示与回答打包进 4096，对提示掩码损失，学习率 1e-5，dropout 0.05，保留 z-loss。提示中的图用加边框的 resize，避免裁掉信息；生成图像时另有裁切策略，训练与推理的几何要配对。评测覆盖 caption、VQA、纯文本（相对 Llama-2 不掉、34B 在部分常识与数学上可过更大对照）、以及新的长文混合模态人工评测。谱系上接 CM3 / CM3Leon 的离散交错，而不是 CLIP+LLM 适配器。</p>',15)),(e(),s(d,null,{default:n(()=>[h(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20IMG%5B%22512%C3%97512%20%E5%9B%BE%E5%83%8F%22%5D%20--%3E%20VQ%5B%22VQ%20%E7%A0%81%E6%9C%AC%208192%20%E2%86%92%201024%20token%22%5D%0A%20%20TXT%5B%22%E6%96%87%E6%9C%AC%22%5D%20--%3E%20BPE%5B%22BPE%20%E8%AF%8D%E8%A1%A8%2065536%22%5D%0A%20%20VQ%20--%3E%20SEQ%5B%22%E4%BA%A4%E9%94%99%E7%A6%BB%E6%95%A3%E5%BA%8F%E5%88%97%22%5D%0A%20%20BPE%20--%3E%20SEQ%0A%20%20SEQ%20--%3E%20TF%5B%22%E7%BB%9F%E4%B8%80%20Transformer%20%2B%20QK-Norm%22%5D%0A%20%20TF%20--%3E%20YT%5B%22%E6%96%87%E6%9C%AC%20token%22%5D%0A%20%20TF%20--%3E%20YI%5B%22%E5%9B%BE%E5%83%8F%E7%A0%81%22%5D%0A%20%20YI%20--%3E%20DEC%5B%22%E5%83%8F%E7%B4%A0%E8%A7%A3%E7%A0%81%E5%99%A8%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[m(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>离散化把「生成图像」收成与写词相同的分类问题，交错是序列的自然形态，不必为插图发明一种新注意力。相对性质是双刃：码本的量化误差进入每一层，文字密集的图在重建阶段已经丢了笔画，后面的 Transformer 无法凭空补 OCR。QK-Norm 控制的是注意力内部的尺度，z-loss 控制的是词表 softmax 的 \\(Z\\)；两者不是同一层的同一病。34B 上 Swin 序归一化是因为 SwiGLU 的门把隐藏范数乘大，预归一化残差会把爆炸传到更深——这是早期融合放大了本已存在的优化脆性，不是图像模态独有的新定律。</p><h3 id="和连续视觉前缀、和扩散衔接" tabindex="-1">和连续视觉前缀、和扩散衔接 <a class="header-anchor" href="#和连续视觉前缀、和扩散衔接" aria-label="Permalink to &quot;和连续视觉前缀、和扩散衔接&quot;">​</a></h3><p>LLaVA 式 MLP 投影、Flamingo 式交叉注意，视觉是连续向量，生成图像通常外挂扩散；Emu 预测连续视觉嵌入再交给扩散解码，仍不是共享词表。<a href="/llm/emu">Emu</a> 与 Chameleon 都做图文混生，前者码是连续的、后者是离散的。离散路线的服务形态是「一个自回归头」；连续路线的服务形态是「语言模型 + 扩散」。不要用「都能出图」把两条账单画等号。</p><p><span class="marginnote">论文把 Gemini 列为最相近的早期融合对照，并明确差异在图像解码是否独立。讨论「原生多模态」时，应分开写：联合训练的数据主张、是否共享离散词表、生成图像是否走同一 LM 头。三件事可以拆开买。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>4K 窗口装不下多张 1024 码的图再加长文；产品级多图文档不是这篇的设定。OCR 上限在 tokenizer。安全：混生能出图，公开权重砍掉生成侧是政策选择，不是模型突然不会了。研究许可不可当商用 Apache 读。不要把 7B 的 dropout 配方抄到 34B，也不要把 34B 的 Swin 序当成 7B 必需——论文写 7B 在 norm-reorder 后也可以不用 dropout，但 QK-Norm 不能省。</p><p>训练稳定性不要只靠降学习率。混合熵下，应先看注意力 logits 范数与最终 \\(Z\\)，再决定是否加 QK-Norm / z-loss。推理时图像码的采样温度与文本温度往往不能共用：图像码更需要多样性，文本需要锋利。若只用文本输出的检查点，服务里应拒绝图像码采样接口，以免「论文能画、权重不能画」变成静默乱码。</p><p>数据配比未在主文展开成可复现表；不要编造「百分之多少是图」。人脸过采样影响生成分布，理解侧评测若不含人脸占比声明，不要外推到证件照 OCR。长文混生的人工评测是新协议，不能直接换成 COCO CIDEr 排序。</p><p><span class="marginnote">出处：Chameleon Team，<em>Chameleon: Mixed-Modal Early-Fusion Foundation Models</em>，arXiv:2405.09818。图像 tokenizer 基于 Gafni 等 2022；交错离散文档谱系见 Aghajanyan 等 CM3 与 Yu 等 CM3Leon。不要给 Chameleon 另编一个 2024 年会议长文号若当时仍是预印本。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Chameleon 用 VQ 图像码与 BPE 共享词表，7B/34B 从零训 4.4T，早期融合自回归图文。</li><li>稳定化靠 QK-Norm、z-loss，34B 另加 Swin 式归一化顺序；无 QK-Norm 会发散。</li><li>与晚融合连续视觉、与带独立图像解码器的 Gemini 不是同一张结构。</li><li>公开权重偏研究与文本输出；OCR 受码本重建限制。</li><li>出处：Chameleon Team，arXiv:2405.09818。</li></ul>',12))])}const f=t(p,[["render",E]]);export{_ as __pageData,f as default};
